const SW = `
const CACHE_NAME = 'math-quest-5aa029bb';
self.addEventListener('install', (e) => {
  self.skipWaiting();
});
self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
      .then(() => clients.claim())
  );
});
self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET') return;
  if (new URL(e.request.url).pathname.indexOf('/api/') === 0) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        const copy = res.clone();
        caches.open(CACHE_NAME).then((c) => c.put(e.request, copy)).catch(() => {});
        return res;
      })
      .catch(() => caches.match(e.request))
  );
});
`;

// =====================================================================
//  OPTIONAL ACCOUNTS  (needs a KV namespace bound as MATH_KV; without it the
//  game works exactly as before and the Account section explains it is off)
// =====================================================================
const PBKDF2_ITERS = 100000;          // Workers' maximum; stored per account so it can be changed later
const SESSION_TTL = 60 * 60 * 24 * 30; // stay signed in for 30 days
const MAX_SAVE_BYTES = ECON.save.hardLimitBytes;
const NAME_RE = /^[a-z0-9_-]{3,20}$/;

function rand(n) { const a = new Uint8Array(n); crypto.getRandomValues(a); return a; }
function toB64(buf) {
  const bytes = new Uint8Array(buf);
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function fromB64(s) {
  const bin = atob(s);
  const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
}
async function hashPassword(pw, salt, iters) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: salt, iterations: iters }, key, 256);
  return toB64(bits);
}
async function sha256Hex(str) {
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  return Array.from(new Uint8Array(d)).map(function (b) { return b.toString(16).padStart(2, '0'); }).join('');
}
function safeEq(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
function json(obj, status) {
  return new Response(JSON.stringify(obj), {
    status: status || 200,
    headers: { 'content-type': 'application/json;charset=UTF-8', 'cache-control': 'no-store' }
  });
}
function validState(s) {
  return !!s && typeof s === 'object' && !Array.isArray(s) && Array.isArray(s.unlockedPets) && typeof s.gems === 'number';
}
async function newSession(kv, name) {
  const token = toB64(rand(32)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  await kv.put('sess:' + await sha256Hex(token), JSON.stringify({ name: name, at: Date.now() }), { expirationTtl: SESSION_TTL });
  return token;
}
async function authenticate(request, kv) {
  const h = request.headers.get('authorization') || '';
  const m = h.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;
  const rec = await kv.get('sess:' + await sha256Hex(m[1]), 'json');
  return rec && rec.name ? { name: rec.name, tokenHash: await sha256Hex(m[1]) } : null;
}
async function checkPassword(kv, name, password) {
  const acct = await kv.get('acct:' + name, 'json');
  if (!acct) return false;
  const h = await hashPassword(password, fromB64(acct.salt), acct.iters || PBKDF2_ITERS);
  return safeEq(h, acct.hash);
}

// ---------------------------------------------------------------------
//  ONLINE DUELS  (async: same questions, scored on the server, gem stakes)
//  KV layout (every key expires after 3 days):
//    duel:<id>           immutable {from,to,stake,qs:[{e,l,o,a}],created}
//    res:<id>:<name>     written only by that player {score,ms,at}
//    duels:<name>:<id>   index entry (metadata) for each participant
//    ping:<name>         last notification for that player
//    decl:<id>           the invited player declined
//    blk:<me>:<them>     me has blocked them (no expiry)
// ---------------------------------------------------------------------
const DUEL_TTL = 60 * 60 * 24 * ECON.duel.ttlDays;
function newDuelId() { return toB64(rand(6)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
async function savedGems(kv, name) {
  const s = await kv.get('save:' + name, 'json');
  return s && s.state && typeof s.state.gems === 'number' ? s.state.gems : 0;
}
function cleanText(t, max, allowSubSup) {
  if (typeof t !== 'string' || t.length > max) return null;
  const bare = allowSubSup ? t.replace(/<\/?(sub|sup)>/g, '') : t;
  return /[<>&"`]/.test(bare) ? null : t;
}
function cleanQuestions(qs) {
  if (!Array.isArray(qs) || [5, 10, 15].indexOf(qs.length) === -1) return null;
  const out = [];
  for (let i = 0; i < qs.length; i++) {
    const q = qs[i] || {};
    const e = cleanText(q.e, 240, true);
    const l = cleanText(q.l == null ? '=' : q.l, 24, false);
    if (!e || l === null) return null;
    if (!Array.isArray(q.o) || q.o.length < 2 || q.o.length > 4) return null;
    const o = q.o.map(Number);
    const a = Number(q.a);
    if (o.some(function (v) { return !isFinite(v) || Math.abs(v) > 1e9; }) || !isFinite(a)) return null;
    if (!o.some(function (v) { return Math.abs(v - a) < 0.0001; })) return null;
    out.push({ e: e, l: l, o: o, a: a });
  }
  return out;
}
async function duelSummary(kv, duel, me) {
  const opp = duel.from === me ? duel.to : duel.from;
  const rs = await Promise.all([kv.get('res:' + duel.id + ':' + me, 'json'), kv.get('res:' + duel.id + ':' + opp, 'json'), kv.get('decl:' + duel.id)]);
  const mine = rs[0], theirs = rs[1];
  const sum = { id: duel.id, from: duel.from, to: duel.to, opp: opp, stake: duel.stake, n: duel.qs.length, created: duel.created, mine: mine ? { score: mine.score, ms: mine.ms } : null, theirs: null, outcome: null, declined: false };
  if (rs[2]) { sum.declined = true; sum.status = 'declined'; return sum; }
  if (!mine) { sum.status = 'todo'; return sum; }
  if (!theirs) { sum.status = 'waiting'; return sum; }
  sum.status = 'done';
  sum.theirs = { score: theirs.score, ms: theirs.ms };
  sum.outcome = mine.score > theirs.score ? 'win' : (mine.score < theirs.score ? 'loss' : (mine.ms < theirs.ms ? 'win' : (mine.ms > theirs.ms ? 'loss' : 'tie')));
  return sum;
}
async function ping(kv, to, id, kind, from) {
  await kv.put('ping:' + to, JSON.stringify({ t: Date.now(), id: id, k: kind, from: from }), { expirationTtl: DUEL_TTL });
}
async function handleDuel(path, request, url, kv, who, body) {
  const me = who.name;
  if (path === '/api/duel/ping' && request.method === 'GET') {
    return json({ ping: (await kv.get('ping:' + me, 'json')) || null });
  }

  if (path === '/api/duel/list' && request.method === 'GET') {
    const l = await kv.list({ prefix: 'duels:' + me + ':', limit: 60 });
    const metas = l.keys.map(function (k) { return k.metadata; }).filter(function (m) { return m && m.id; });
    metas.sort(function (a, b) { return b.created - a.created; });
    const duels = (await Promise.all(metas.slice(0, 12).map(async function (m) {
      const d = await kv.get('duel:' + m.id, 'json');
      return d ? duelSummary(kv, d, me) : null;
    }))).filter(Boolean);
    return json({ duels: duels });
  }

  if (path === '/api/duel/get' && request.method === 'GET') {
    const id = String(url.searchParams.get('id') || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || (d.from !== me && d.to !== me)) return json({ error: 'That duel is not available any more.' }, 404);
    const sum = await duelSummary(kv, d, me);
    return json({ duel: { id: d.id, from: d.from, to: d.to, stake: d.stake, qs: d.qs.map(function (q) { return { e: q.e, l: q.l, o: q.o }; }) }, summary: sum });
  }

  if (path === '/api/duel/create' && request.method === 'POST') {
    const to = String(body.to || '').trim().toLowerCase();
    const stake = Number(body.stake);
    if (!NAME_RE.test(to) || to === me) return json({ error: 'Type the player name of a friend.' }, 400);
    if (ECON.duel.stakes.indexOf(stake) === -1) return json({ error: 'Pick one of the stake choices.' }, 400);
    const qs = cleanQuestions(body.qs);
    if (!qs) return json({ error: 'Those questions were not valid.' }, 400);
    if (!(await kv.get('acct:' + to)) || (await kv.get('blk:' + to + ':' + me))) return json({ error: 'No player called "' + to + '" can be challenged right now.' }, 404);
    const rlKey = 'rl:' + me;
    const used = parseInt((await kv.get(rlKey)) || '0', 10);
    if (used >= ECON.duel.maxPerHour) return json({ error: 'Lots of challenges! Take a short break and try again soon.' }, 429);
    if (stake > 0) {
      const gems = await Promise.all([savedGems(kv, me), savedGems(kv, to)]);
      if (!stakeAllowed(stake, gems[0])) return json({ error: 'You can stake at most half of your gems.' }, 400);
      if (!stakeAllowed(stake, gems[1])) return json({ error: 'That friend cannot cover this stake. Try a smaller one.' }, 400);
    }
    await kv.put(rlKey, String(used + 1), { expirationTtl: 3600 });
    const id = newDuelId();
    const duel = { id: id, from: me, to: to, stake: stake, qs: qs, created: Date.now() };
    const meta = { id: id, created: duel.created };
    await Promise.all([
      kv.put('duel:' + id, JSON.stringify(duel), { expirationTtl: DUEL_TTL }),
      kv.put('duels:' + me + ':' + id, '1', { expirationTtl: DUEL_TTL, metadata: meta }),
      kv.put('duels:' + to + ':' + id, '1', { expirationTtl: DUEL_TTL, metadata: meta })
    ]);
    await ping(kv, to, id, 'invite', me);
    return json({ ok: true, id: id });
  }

  if (path === '/api/duel/submit' && request.method === 'POST') {
    const id = String(body.id || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || (d.from !== me && d.to !== me)) return json({ error: 'That duel is not available any more.' }, 404);
    if (await kv.get('decl:' + id)) return json({ error: 'That challenge was declined.' }, 409);
    const resKey = 'res:' + id + ':' + me;
    if (!(await kv.get(resKey))) {
      const ans = Array.isArray(body.answers) ? body.answers : [];
      if (ans.length !== d.qs.length) return json({ error: 'Answer every question first.' }, 400);
      let score = 0;
      d.qs.forEach(function (q, i) { if (Math.abs(Number(ans[i]) - q.a) < 0.0001) score += 1; });
      const ms = Math.min(900000, Math.max(d.qs.length * 400, Math.round(Number(body.ms) || 0)));
      await kv.put(resKey, JSON.stringify({ score: score, ms: ms, at: Date.now() }), { expirationTtl: DUEL_TTL });
      const other = d.from === me ? d.to : d.from;
      // if they have not played yet this is still an invitation ("your turn"); otherwise it is the result
      await ping(kv, other, id, (await kv.get('res:' + id + ':' + other)) ? 'result' : 'invite', me);
    }
    return json({ ok: true, summary: await duelSummary(kv, d, me) });
  }

  if (path === '/api/duel/decline' && request.method === 'POST') {
    const id = String(body.id || '');
    const d = /^[A-Za-z0-9_-]{6,12}$/.test(id) ? await kv.get('duel:' + id, 'json') : null;
    if (!d || d.to !== me) return json({ error: 'That duel is not available any more.' }, 404);
    if (!(await kv.get('res:' + id + ':' + me))) {
      await kv.put('decl:' + id, '1', { expirationTtl: DUEL_TTL });
      await ping(kv, d.from, id, 'declined', me);
    }
    return json({ ok: true });
  }

  if (path === '/api/duel/block' && request.method === 'POST') {
    const name = String(body.name || '').trim().toLowerCase();
    if (!NAME_RE.test(name) || name === me) return json({ error: 'Bad name' }, 400);
    await kv.put('blk:' + me + ':' + name, '1');
    return json({ ok: true });
  }

  return json({ error: 'Not found' }, 404);
}

async function handleApi(request, env, url) {
  const path = url.pathname;
  if (path === '/api/status') return json({ enabled: !!env.MATH_KV });
  const kv = env.MATH_KV;
  if (!kv) return json({ error: 'Online accounts are not set up on this server yet.' }, 501);
  if (request.method !== 'GET' && request.method !== 'POST' && request.method !== 'PUT') return json({ error: 'Method not allowed' }, 405);

  let body = {};
  if (request.method !== 'GET') {
    try {
      const txt = await request.text();
      if (txt.length > MAX_SAVE_BYTES + 5000) return json({ error: 'Too large' }, 413);
      body = txt ? JSON.parse(txt) : {};
    } catch (e) { return json({ error: 'Bad request' }, 400); }
  }

  if (path === '/api/register' && request.method === 'POST') {
    const name = String(body.name || '').trim().toLowerCase();
    const password = String(body.password || '');
    if (!NAME_RE.test(name)) return json({ error: 'Player names are 3-20 letters, numbers, - or _.' }, 400);
    if (password.length < 6 || password.length > 100) return json({ error: 'Passwords need at least 6 characters.' }, 400);
    if (await kv.get('acct:' + name)) return json({ error: 'That player name is taken. Try another!' }, 409);
    const salt = rand(16);
    const hash = await hashPassword(password, salt, PBKDF2_ITERS);
    await kv.put('acct:' + name, JSON.stringify({ salt: toB64(salt), hash: hash, iters: PBKDF2_ITERS, created: Date.now() }));
    let version = 0;
    if (validState(body.state) && JSON.stringify(body.state).length <= MAX_SAVE_BYTES) {
      version = 1;
      await kv.put('save:' + name, JSON.stringify({ state: body.state, version: 1, updatedAt: Date.now() }));
    }
    return json({ ok: true, name: name, token: await newSession(kv, name), version: version });
  }

  if (path === '/api/login' && request.method === 'POST') {
    const name = String(body.name || '').trim().toLowerCase();
    const password = String(body.password || '');
    const failKey = 'fail:' + name;
    const fails = parseInt((await kv.get(failKey)) || '0', 10);
    if (fails >= 8) return json({ error: 'Too many tries. Please wait 15 minutes and try again.' }, 429);
    if (!NAME_RE.test(name) || !password || !(await checkPassword(kv, name, password))) {
      if (NAME_RE.test(name)) await kv.put(failKey, String(fails + 1), { expirationTtl: 900 });
      return json({ error: 'Wrong player name or password.' }, 401);
    }
    await kv.delete(failKey);
    const save = await kv.get('save:' + name, 'json');
    return json({ ok: true, name: name, token: await newSession(kv, name), save: save || null });
  }

  const who = await authenticate(request, kv);
  if (!who) return json({ error: 'Please sign in again.' }, 401);

  if (path === '/api/save' && request.method === 'GET') {
    return json({ save: (await kv.get('save:' + who.name, 'json')) || null });
  }

  if (path === '/api/save' && request.method === 'PUT') {
    if (!validState(body.state)) return json({ error: 'Invalid save' }, 400);
    if (JSON.stringify(body.state).length > MAX_SAVE_BYTES) return json({ error: 'Save too large' }, 413);
    const cur = await kv.get('save:' + who.name, 'json');
    const curVersion = cur ? cur.version : 0;
    if (!body.force && Number(body.baseVersion) !== curVersion) return json({ conflict: true, save: cur || null }, 409);
    const next = { state: body.state, version: curVersion + 1, updatedAt: Date.now() };
    await kv.put('save:' + who.name, JSON.stringify(next));
    return json({ ok: true, version: next.version, updatedAt: next.updatedAt });
  }

  if (path.indexOf('/api/duel/') === 0) return handleDuel(path, request, url, kv, who, body);

  if (path === '/api/logout' && request.method === 'POST') {
    await kv.delete('sess:' + who.tokenHash);
    return json({ ok: true });
  }

  if (path === '/api/delete' && request.method === 'POST') {
    if (!(await checkPassword(kv, who.name, String(body.password || '')))) return json({ error: 'Wrong password.' }, 401);
    await kv.delete('acct:' + who.name);
    await kv.delete('save:' + who.name);
    await kv.delete('sess:' + who.tokenHash);
    return json({ ok: true });
  }

  return json({ error: 'Not found' }, 404);
}

// Headers added to every response. The page needs inline script/style (it is one self-contained file),
// but nothing may load from, or send data to, any other site.
const SECURITY_HEADERS = {
  'content-security-policy': "upgrade-insecure-requests; default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; manifest-src 'self'; worker-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
  // browsers that reached us over https must keep using https (ignored over http; no includeSubDomains so other sites on the domain are untouched)
  'strict-transport-security': 'max-age=15552000',
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'no-referrer',
  'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=()',
  'x-frame-options': 'DENY'
};
function withSecurityHeaders(res) {
  const out = new Response(res.body, res);
  Object.keys(SECURITY_HEADERS).forEach(function (k) { out.headers.set(k, SECURITY_HEADERS[k]); });
  return out;
}

// Plain http gets sent to https (browsers label http pages "Not secure" and many school and office filters block them).
// Cloudflare tells us how the visitor really connected in the cf-visitor header. Local development stays on http.
function insecureRequest(request, url) {
  if (/^(localhost|127\.0\.0\.1|\[::1\])$/.test(url.hostname) || /\.localhost$/.test(url.hostname)) return false;
  return url.protocol === 'http:' || /"scheme"\s*:\s*"http"/.test(request.headers.get('cf-visitor') || '');
}

async function route(request, env, ctx) {
    const url = new URL(request.url);
    if (insecureRequest(request, url)) {
      url.protocol = 'https:';
      return new Response(null, { status: 301, headers: { location: url.toString(), 'cache-control': 'no-store' } });
    }

    if (url.pathname.startsWith("/api/")) {
      try {
        return await handleApi(request, env, url);
      } catch (e) {
        return json({ error: 'Something went wrong. Please try again.' }, 500);
      }
    }

    if (url.pathname === "/manifest.json") {
      return new Response(JSON.stringify(MANIFEST), {
        headers: {
          "content-type": "application/manifest+json;charset=UTF-8",
          "cache-control": "public, max-age=86400"
        }
      });
    }

    if (url.pathname === "/sw.js") {
      return new Response(SW, {
        headers: {
          "content-type": "application/javascript;charset=UTF-8",
          "cache-control": "public, max-age=0"
        }
      });
    }

    return new Response(HTML, {
      headers: {
        "content-type": "text/html;charset=UTF-8",
        "cache-control": "no-cache"
      }
    });
  }

export default {
  async fetch(request, env, ctx) {
    return withSecurityHeaders(await route(request, env, ctx));
  }
};
